function calculate_item_amount(frm, cdt, cdn) {
    let item = locals[cdt][cdn];
    let amount = flt(item.qty) * flt(item.rate);
    frappe.model.set_value(cdt, cdn, 'amount', amount);

    calculate_all_totals(frm);
}

function calculate_all_totals(frm) {
    let grand_total = 0;
    (frm.doc.items || []).forEach(function(item) {
        grand_total += flt(item.amount) || (flt(item.qty) * flt(item.rate));
    });
    frm.set_value('custom_grand_total', grand_total);

    let total_vat = 0;
    if (frm.doc.custom_vat_override == 1) {
        total_vat = flt(frm.doc.custom_vat);
    } else {
        (frm.doc.items || []).forEach(function(row) {
            if (row.custom_vat_nocal == 0 || !row.custom_vat_nocal) {
                let amount = flt(row.amount) || (flt(row.qty) * flt(row.rate));
                total_vat += (amount * 0.07);
            }
        });
        frm.set_value('custom_vat', total_vat);
    }

    let paid_amount = grand_total + total_vat;
    frm.set_value('custom_paid_amount', paid_amount);

    update_thai_baht_text(frm);
}

function update_thai_baht_text(frm) {
    let paid_amount = flt(frm.doc.custom_paid_amount);

    if (paid_amount > 0) {
        let thai_words = thai_baht_text(paid_amount);
        frm.set_value('custom_in_words', thai_words);
    } else {
        frm.set_value('custom_in_words', 'ศูนย์บาทถ้วน');
    }
}

function thai_baht_text(number) {
    number = parseFloat(number).toFixed(2);
    let numberArray = number.split('.');
    let baht = numberArray[0];
    let satang = numberArray[1];

    let bahtText = convert_to_thai_text(baht);
    let satangText = convert_to_thai_text(satang);

    let result = '';

    if (bahtText) {
        result += bahtText + 'บาท';
    }

    if (satangText && satang !== '00') {
        result += satangText + 'สตางค์';
    } else {
        result += 'ถ้วน';
    }

    return result;
}

function convert_to_thai_text(numberStr) {
    let thaiNumbers = ['ศูนย์', 'หนึ่ง', 'สอง', 'สาม', 'สี่', 'ห้า', 'หก', 'เจ็ด', 'แปด', 'เก้า'];
    let thaiPositions = ['', 'สิบ', 'ร้อย', 'พัน', 'หมื่น', 'แสน', 'ล้าน'];

    let text = '';
    let length = numberStr.length;

    if (length > 1) {
        numberStr = parseInt(numberStr, 10).toString();
        length = numberStr.length;
    }

    if (numberStr === '0') return '';

    for (let i = 0; i < length; i++) {
        let digit = parseInt(numberStr.charAt(i), 10);
        let position = length - i - 1;

        if (digit !== 0) {
            if (position === 0 && digit === 1 && length > 1) {
                text += 'เอ็ด';
            } 
            else if (position === 1 && digit === 2) {
                text += 'ยี่สิบ';
            } 
            else if (position === 1 && digit === 1) {
                text += 'สิบ';
            } 
            else {
                text += thaiNumbers[digit] + thaiPositions[position];
            }
        }
    }
    return text;
}

