                order_by: 'creation desc'
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    let all_data = r.message;

                    // 1. หาค่าสูงสุด-ต่ำสุด จากประวัติทั้งหมด (All time)
