// Client Script: Sales Invoice - Manual WHT / Retention Override
// DocType: Sales Invoice | Apply To: Form
//
// สคริปต์เสริมชั่วคราว — ไม่แก้สคริปต์เดิมใน custom app
//
// หลักการ:
// สคริปต์เดิมเรียก calculate_paid_amount() ทุกครั้งที่ validate / refresh
// แล้วเขียนค่าคำนวณทับ ค่าที่แก้เองจึงหายตอนกด Save
// สคริปต์นี้ "กัน" การเขียนทับ 2 จุด เมื่อติ๊ก custom_edit_wht / custom_edit_retention
//   1) frm.set_value('custom_wht_amount' | 'custom_retention_amount')  -> ไม่ให้ทับ
//   2) frappe.model.set_value(แถวในตาราง, 'amount')                     -> บังคับให้เท่ายอดที่กรอกเอง
// ส่วนยอดรวมหัก / ยอดสุทธิ / คำอ่านภาษาไทย ยังให้สคริปต์เดิมคำนวณจากตารางตามปกติ

(function () {
    const DOCTYPE = 'Sales Invoice';
    const TABLE = 'custom_payment_entry_deduction';

    // event ของสคริปต์เดิมที่เรียก calculate_paid_amount()
    // ใช้สั่งให้สคริปต์เดิมคำนวณยอดรวมใหม่ หลังยอดในตารางเปลี่ยน
    const RECALC_EVENT = 'custom_wht_percent';

    const OVERRIDES = [
        {
            edit: 'custom_edit_wht',
            subject: 'custom_subject_to_wht',
            percent: 'custom_wht_percent',
            amount: 'custom_wht_amount',
            // ต้องหาชื่อบัญชีแบบเดียวกับสคริปต์เดิม
            account: (frm) => frm.custom_wht_acc || `ถูกหัก ณ ที่จ่าย - ${frm.custom_abbr || ''}`,
        },
        {
            edit: 'custom_edit_retention',
            subject: 'custom_subject_to_retention',
            percent: 'custom_retention_percent',
            amount: 'custom_retention_amount',
            account: (frm) => frm.custom_ret_acc || `เงินประกันผลงาน - ${frm.custom_abbr || ''}`,
        },
    ];

    function calculated_amount(frm, o) {
        return flt(flt(frm.doc.net_total) * flt(frm.doc[o.percent]) / 100, 2);
    }

    // คืนยอดที่กรอกเอง (> 0) ถ้าโหมดแก้ไขเองทำงานอยู่ / คืน 0 ถ้าให้ใช้ค่าคำนวณตามปกติ
    function get_manual_amount(frm, o) {
        if (!frm.doc[o.edit] || !frm.doc[o.subject]) return 0;
        // ถ้าค่าคำนวณ <= 0 สคริปต์เดิมจะลบแถวในตารางทิ้ง จึงไม่ override
        if (calculated_amount(frm, o) <= 0) return 0;
        const manual = flt(frm.doc[o.amount], 2);
        // ถ้ายังไม่ได้กรอก (0) ปล่อยให้สคริปต์เดิมใส่ค่าคำนวณเป็นค่าเริ่มต้น
        return manual > 0 ? manual : 0;
    }

    // --- จุดกันที่ 1: ยอดที่หัวเอกสาร ---
    function install_form_guard(frm) {
        if (frm.__manual_deduction_guard) return;
        frm.__manual_deduction_guard = true;

        const set_value = frm.set_value;
        frm.set_value = function (field, ...args) {
            if (typeof field === 'string') {
                const o = OVERRIDES.find((x) => x.amount === field);
                if (o && get_manual_amount(frm, o) > 0) {
                    return Promise.resolve(); // ไม่ให้ค่าคำนวณทับค่าที่กรอกเอง
                }
            }
            return set_value.call(frm, field, ...args);
        };
    }

    // --- จุดกันที่ 2: ยอด amount ของแถวในตาราง ---
    function install_model_guard() {
        if (frappe.model.__manual_deduction_guard) return;
        frappe.model.__manual_deduction_guard = true;

        const set_value = frappe.model.set_value;
        frappe.model.set_value = function (doctype, docname, fieldname, value, ...rest) {
            if (fieldname === 'amount') {
                try {
                    const row = (locals[doctype] || {})[docname];
                    const frm = window.cur_frm;
                    if (
                        row && row.parenttype === DOCTYPE && row.parentfield === TABLE &&
                        frm && frm.doctype === DOCTYPE && frm.doc.name === row.parent
                    ) {
                        const o = OVERRIDES.find((x) => x.account(frm) === row.account);
                        const manual = o ? get_manual_amount(frm, o) : 0;
                        if (manual > 0) {
                            if (flt(row.amount) === manual) return Promise.resolve();
                            value = manual; // บังคับให้เท่ายอดที่กรอกเองเสมอ
                        }
                    }
                } catch (e) {
                    console.error('Manual deduction override:', e);
                }
            }
            return set_value.call(frappe.model, doctype, docname, fieldname, value, ...rest);
        };
    }

    // เปิด/ปิดการแก้ไขช่องยอดเงินตาม checkbox
    function toggle_editable(frm) {
        OVERRIDES.forEach((o) => {
            if (!frm.fields_dict[o.amount]) return;
            const editable = frm.doc[o.edit] && frm.doc[o.subject];
            frm.set_df_property(o.amount, 'read_only', editable ? 0 : 1);
        });
    }

    // ดันยอดที่กรอกเองลงแถวในตาราง (แถวแรกของบัญชีนั้น เหมือนสคริปต์เดิม)
    function sync_rows(frm) {
        if (frm.doc.docstatus !== 0) return false;
        let changed = false;

        OVERRIDES.forEach((o) => {
            const manual = get_manual_amount(frm, o);
            if (manual <= 0) return;

            const account = o.account(frm);
            const row = (frm.doc[TABLE] || []).find((d) => d.account === account);
            if (row && flt(row.amount) !== manual) {
                frappe.model.set_value(row.doctype, row.name, 'amount', manual);
                changed = true;
            }
        });
        return changed;
    }

    // ให้สคริปต์เดิมคำนวณ ยอดรวมหัก / ยอดสุทธิ / คำอ่าน ใหม่จากตาราง
    function recalculate(frm) {
        return frm.trigger(RECALC_EVENT);
    }

    function apply_manual(frm) {
        if (sync_rows(frm)) return recalculate(frm);
    }

    install_model_guard();

    const handlers = {
        setup(frm) {
            install_form_guard(frm);
        },
        onload(frm) {
            install_form_guard(frm);
        },
        refresh(frm) {
            install_form_guard(frm);
            toggle_editable(frm);
            return apply_manual(frm);
        },
        // ทำงานต่อจาก validate ของสคริปต์เดิม เป็นด่านสุดท้ายก่อนส่งไป Save
        validate(frm) {
            return apply_manual(frm);
        },
    };

    OVERRIDES.forEach((o) => {
        // ติ๊ก/ไม่ติ๊ก "แก้ไขเอง": ถ้าเอาติ๊กออก ยอดจะกลับเป็นค่าคำนวณ
        handlers[o.edit] = (frm) => {
            toggle_editable(frm);
            return recalculate(frm);
        };
        handlers[o.subject] = (frm) => toggle_editable(frm);
        // แก้ยอดที่หัวเอกสาร -> อัปเดตแถวในตาราง + ยอดรวม
        handlers[o.amount] = (frm) => {
            if (sync_rows(frm)) return recalculate(frm);
            // ลบยอดจนเป็น 0 ขณะติ๊กแก้ไขเอง = กลับไปใช้ค่าคำนวณทันที
            if (frm.doc.docstatus === 0 && frm.doc[o.edit] && flt(frm.doc[o.amount]) <= 0) {
                return recalculate(frm);
            }
        };
    });

    frappe.ui.form.on(DOCTYPE, handlers);
})();

// Client Script — DocType: Material Request (Apply To: Form)
// รวมยอดจาก items.amount, แยกยอดที่ไม่คิด VAT, คำนวณ VAT 7%, รองรับราคารวม VAT
// และ override VAT จากนั้นแปลง custom_grand_total เป็นตัวอักษรไทยใน custom_in_words

const VAT_RATE = 7;

frappe.ui.form.on('Material Request', {
    validate(frm) {
        calculate_totals(frm, true);   // ตอน save ใส่ค่าตรงลง doc เพื่อให้บันทึกแน่นอน
    },
    custom_included_vat(frm) {
        calculate_totals(frm);
    },
    custom_vat_override(frm) {
        calculate_totals(frm);
    },
    custom_vat(frm) {
        // ถ้าไม่ได้ override ค่า VAT มาจากการคำนวณอยู่แล้ว ไม่ต้องคำนวณซ้ำ (กัน loop)
        if (frm.doc.custom_vat_override) calculate_totals(frm);
    },
    custom_grand_total(frm) {
        update_thai_baht_text(frm);
    }
});

frappe.ui.form.on('Material Request Item', {
    qty(frm)              { schedule_calculate(frm); },
    rate(frm)             { schedule_calculate(frm); },
    amount(frm)           { schedule_calculate(frm); },
    custom_vat_nocal(frm) { schedule_calculate(frm); },
    items_remove(frm)     { schedule_calculate(frm); }
});

// รวม event ที่ยิงติดกัน (qty → amount) ให้คำนวณครั้งเดียวหลังค่าในแถวนิ่งแล้ว
let _calc_timer = null;
function schedule_calculate(frm) {
    clearTimeout(_calc_timer);
    _calc_timer = setTimeout(() => calculate_totals(frm), 150);
}

function calculate_totals(frm, direct = false) {
    let sum_vat = 0;     // ยอดที่ต้องคิด VAT
    let sum_novat = 0;   // ยอดที่ไม่คิด VAT (custom_vat_nocal = 1)

    (frm.doc.items || []).forEach(row => {
        // คำนวณจาก qty * rate โดยตรง เพราะตอน event qty/rate ทำงาน
        // row.amount อาจยังเป็นค่าเก่า (ERPNext อัปเดตทีหลัง)
        let amount = flt(row.rate)
            ? flt(row.qty) * flt(row.rate)
            : flt(row.amount);
        if (cint(row.custom_vat_nocal)) {
            sum_novat += amount;
        } else {
            sum_vat += amount;
        }
    });

    let net_total, vat;

    if (cint(frm.doc.custom_vat_override)) {
        // ใช้ค่า VAT ที่ผู้ใช้กรอกเอง
        vat = flt(frm.doc.custom_vat, 2);
        net_total = cint(frm.doc.custom_included_vat) ? sum_vat - vat : sum_vat;
    } else if (cint(frm.doc.custom_included_vat)) {
        // amount รวม VAT แล้ว → ถอดยอดก่อนภาษี
        net_total = sum_vat * 100 / (100 + VAT_RATE);
        vat = sum_vat - net_total;
    } else {
        net_total = sum_vat;
        vat = sum_vat * VAT_RATE / 100;
    }

    net_total = flt(net_total, 2);
    vat = flt(vat, 2);
    sum_novat = flt(sum_novat, 2);

    let grand_total = flt(net_total + vat + sum_novat, 2);

    let values = {
        custom_net_total: net_total,
        custom_net_total_novat: sum_novat,
        custom_grand_total: grand_total,
        custom_in_words: thai_baht_text(grand_total)
    };
    if (!cint(frm.doc.custom_vat_override)) {
        values.custom_vat = vat;
    }

    apply_values(frm, values, direct);
}

function update_thai_baht_text(frm) {
    let text = thai_baht_text(frm.doc.custom_grand_total);
    if (frm.doc.custom_in_words !== text) {
        frm.set_value('custom_in_words', text);
    }
}

// ตั้งค่าเฉพาะ field ที่เปลี่ยนจริง เพื่อไม่ให้ฟอร์ม dirty โดยไม่จำเป็น
function apply_values(frm, values, direct) {
    let changed = {};
    Object.keys(values).forEach(f => {
        if (frm.doc[f] !== values[f]) changed[f] = values[f];
    });
    if (!Object.keys(changed).length) return;

    if (direct) {
        Object.assign(frm.doc, changed);
        Object.keys(changed).forEach(f => frm.refresh_field(f));
    } else {
        frm.set_value(changed);
    }
}

// ---------- แปลงตัวเลขเป็นคำอ่านภาษาไทย ----------

function thai_baht_text(number) {
    number = flt(number);
    let negative = number < 0;
    // ปัดเป็นสตางค์ด้วยจำนวนเต็ม เลี่ยงปัญหาทศนิยม float
    let total_satang = Math.round(Math.abs(number) * 100);
    let baht = Math.floor(total_satang / 100);
    let satang = total_satang % 100;

    if (baht === 0 && satang === 0) return 'ศูนย์บาทถ้วน';

    let result = '';
    if (baht > 0) result += read_thai_number(String(baht)) + 'บาท';
    result += satang > 0 ? read_thai_number(String(satang)) + 'สตางค์' : 'ถ้วน';

    return (negative ? 'ลบ' : '') + result;
}

// อ่านจำนวนเต็มทุกขนาด (รองรับเกินล้าน เช่น หนึ่งล้านล้าน)
function read_thai_number(str) {
    str = str.replace(/^0+/, '');
    if (!str) return '';

    if (str.length > 6) {
        let head = str.slice(0, -6);
        let tail = str.slice(-6);
        return read_thai_number(head) + 'ล้าน' + read_six_digits(tail, true);
    }
    return read_six_digits(str, false);
}

function read_six_digits(str, has_higher) {
    const digits = ['', 'หนึ่ง', 'สอง', 'สาม', 'สี่', 'ห้า', 'หก', 'เจ็ด', 'แปด', 'เก้า'];
    const positions = ['', 'สิบ', 'ร้อย', 'พัน', 'หมื่น', 'แสน'];

    str = str.replace(/^0+/, '');
    let text = '';
    let len = str.length;

    for (let i = 0; i < len; i++) {
        let d = parseInt(str[i], 10);
        let pos = len - i - 1;
        if (d === 0) continue;

        if (pos === 0 && d === 1 && (len > 1 || has_higher)) {
            text += 'เอ็ด';                 // 11, 101, 1,000,001
        } else if (pos === 1 && d === 1) {
            text += 'สิบ';                  // 10–19
        } else if (pos === 1 && d === 2) {
            text += 'ยี่สิบ';                // 20–29
        } else {
            text += digits[d] + positions[pos];
        }
    }
    return text;
}

// ---- ตัวช่วย: สร้าง frappe.ui.stepper ----
frappe.ui.stepper = frappe.ui.stepper || function ({ steps, current = 0, status = 'normal' }) {
  return `
    <div style="display:flex;gap:8px;margin:8px 0 16px">
      ${steps.map((step, i) => {
        const done = i < current || (i === current && status === 'complete');
        const active = i === current;
        let bg = 'var(--gray-300)';
        if (active && status === 'error') bg = 'var(--red-500)';
        else if (done) bg = 'var(--green-500)';
        else if (active) bg = 'var(--primary)';

        return `<div style="flex:1;text-align:center">
          <div style="height:6px;border-radius:3px;background:${bg}"></div>
          <div style="font-size:12px;margin-top:6px;${active ? 'font-weight:600' : 'color:var(--text-muted)'}">
            ${i + 1}. ${__(step.label)}
          </div>
        </div>`;
      }).join('')}
    </div>`;
};

// ---- ใช้งานในฟอร์ม ----
frappe.ui.form.on('Material Request', {
  refresh(frm) { render_stepper(frm); },
  after_save(frm) { render_stepper(frm); }
});

function render_stepper(frm) {
  const cancelled = frm.doc.docstatus === 2;
  let current = frm.doc.docstatus >= 1 ? 2 : frm.is_new() ? 0 : 1;

  const html = frappe.ui.stepper({
    steps: [
      { label: 'Draft' },
      { label: 'Review' },
      { label: cancelled ? 'Cancelled' : 'Done' }
    ],
    current: current,
    status: cancelled ? 'error' : (current === 2 ? 'complete' : 'normal')
  });

  frm.fields_dict.custom_stepper_html.$wrapper.html(html);
}

// =====================================================================
// Client Script : Letter In  (Apply To: Form)
// Flow: Submit -> เสนออนุมัติ -> พิจารณาอนุมัติ (อนุมัติ / ไม่อนุมัติ)
//       ระหว่างรอ: เปลี่ยนผู้อนุมัติ / ถอนเรื่อง
// =====================================================================

const LI = {
